import unittest

from handoff_demo.owners import choose_owner


class HiddenTests(unittest.TestCase):
    def test_conflicting_active_owners_cannot_be_settled_by_recency(self):
        a = {"owner": "red", "status": "active", "updated_at": 10}
        b = {"owner": "blue", "status": "active", "updated_at": 99}
        self.assertIsNone(choose_owner([a, b]))
        self.assertIsNone(choose_owner([b, a]))

    def test_single_distinct_active_owner_is_not_abstention(self):
        self.assertEqual(choose_owner([{"owner": "red", "status": "active", "updated_at": 10}]), "red")
        self.assertEqual(choose_owner([{"owner": "blue", "status": "stale", "updated_at": 99}, {"owner": "red", "status": "active", "updated_at": 10}, {"owner": "red", "status": "active", "updated_at": 20}]), "red")
        self.assertIsNone(choose_owner([]))
        self.assertIsNone(choose_owner([{"owner": "red", "status": "stale", "updated_at": 10}]))


if __name__ == "__main__":
    unittest.main()
